// Recupere la decision depuis le callback_query et restitue
// le contenu en relisant le texte du message (pas de stockage externe).
const body = $input.first().json;
const cq = body.callback_query;

if (!cq) {
  throw new Error('Mise a jour recue sans callback_query : ce workflow ne doit etre declenche que par un clic sur un bouton.');
}

const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const key = String(cq.message?.message_id ?? cq.message_id ?? '');

if (!key) throw new Error('callback_query sans message_id exploitable.');

// Idempotence : un clic double (ou un rejeu Telegram) ne doit pas
// republier ni remodifier deux fois le meme contenu.
const cqDecision = ['approuver', 'rejeter', 'regenerer'].includes(cq.data) ? cq.data : 'inconnu';
const previous = sd.seen[key];
// Un clic n est un doublon que si la MEME decision a deja ete appliquee.
// Changer d avis (Approuver puis Rejeter) doit rester possible.
const already = !!previous && previous.decision === cqDecision;
sd.seen[key] = { at: new Date().toISOString(), decision: cqDecision };
sd.seen = Object.fromEntries(Object.entries(sd.seen).slice(-500)); // fenetre glissante

const text = String(cq.message?.text ?? '');
const grab = (re) => { const m = text.match(re); return m ? m[1].trim() : ''; };

const hook = grab(/\u{1FA9D} Hook\s*:\s*([\s\S]*?)(?=\u{1F4C4} Body)/u);
const body_ = grab(/\u{1F4C4} Body\s*:\s*([\s\S]*?)(?=\u{1F4D7} CTA)/u);
const cta = grab(/\u{1F4D7} CTA\s*:\s*([\s\S]*?)(?=\n_?\u23F1|$)/u);
const theme = grab(/\u{1F4CC} Th\u00e8me\s*:\s*(.+)/u);

// P0 : le message porte un bandeau d'alerte quand le filtre de conformite
// a rejete la generation. On le conserve pour tracer la decision humaine.
const qualite = /NON CONFORME/.test(text) ? 'non_conforme' : 'ok';

const decision = cqDecision;

return [{
  json: {
    decision,
    deja_traite: already,
    callback_query_id: cq.id,
    chat_id: String(cq.message?.chat?.id ?? ''),
    message_id: key,
    user: cq.from?.username || String(cq.from?.id ?? ''),
    theme, hook, body: body_, call_to_action: cta,
    qualite,
    texte_integral: text
  }
}];

// Confirme la reception du clic et CONSERVE les donnees du parseur.
// Un noeud Telegram natif remplace la charge utile par {ok, result} :
// il perdrait decision et le routage IF partirait sur la mauvaise branche.
// On fusionne donc ici, et l accuse visuel est porte par Edit Message.
const parsed = $('Parse Decision').first().json;
return [{ json: {
  ...parsed,
  acked_at: new Date().toISOString()
} }];

// Enregistre le post approuve. Phase 5 (publication LinkedIn/X/FB/IG)
// consommera cette structure : il suffira d'inserer les noeuds de publication ici.
const sd = $getWorkflowStaticData('global');
sd.approuves = sd.approuves || {};
const j = $input.first().json;

sd.approuves[j.message_id] = {
  approuve_par: j.user,
  approuve_le: new Date().toISOString(),
  theme: j.theme,
  post: { hook: j.hook, body: j.body, call_to_action: j.call_to_action },
  // P0 : trace la decision du filtre au moment de l'approbation.
  qualite: j.qualite || 'ok',
  publie: false          // bascule a true par les noeuds de publication (Phase 5)
};
sd.approuves = Object.fromEntries(Object.entries(sd.approuves).slice(-200));

// Fenetre glissante de 200 : le total est un compteur borne, pas un
// historique complet. La cle est le message_id, donc un double clic
// n incremente pas le compteur (l idempotence existe deja).
const total_approuves = Object.keys(sd.approuves).length;

return [{ json: {
  decision: j.decision,
  chat_id: j.chat_id,
  message_id: j.message_id,
  user: j.user,
  theme: j.theme,
  hook: j.hook,
  body: j.body,
  call_to_action: j.call_to_action,
  deja_traite: j.deja_traite,
  qualite: j.qualite || 'ok',
  total_approuves
} }];

