// Isole le chat du circuit d'approbation.
// Un bot Telegram ne recoit PAS ses propres messages, mais un garde-fou reste
// necessaire : une piece jointe, une commande, ou un autre chat doivent etre
// ignores SANS consommer une generation de 23 s.
const body = $input.first().json;

// Telegram n autorise qu UN webhook par jeton : ce workflow sert donc aussi de
// point d'entree du chat. Toute erreur ici tuerait l'approbation, d'ou le throw
// explicite plutot qu'un silence.
const msg = body.message;
if (!msg) throw new Error('ni callback_query ni message : declenchement inattendu.');

const ALLOWED_CHAT = '5387896782';
const chat_id = String(msg.chat?.id ?? '');
if (chat_id !== ALLOWED_CHAT) {
  return [{ json: { ignore: true, raison: 'chat non autorise (' + chat_id + ')' } }];
}
if (msg.from?.is_bot) {
  return [{ json: { ignore: true, raison: 'message emanant d un bot' } }];
}
const text = String(msg.text ?? '').trim();
if (!text) {
  return [{ json: { ignore: true, raison: 'pas de texte (media, sticker, service)' } }];
}
// Les commandes ne declenchent pas de reponse : elles_eviteraient une boucle
// si le bot se reparlait a lui-meme via une commande.
if (text.startsWith('/')) {
  return [{ json: { ignore: true, raison: 'commande : ' + text.split(' ')[0] } }];
}

return [{ json: {
  ignore: false,
  chat_id,
  message_id: String(msg.message_id ?? ''),
  user: msg.from?.username || String(msg.from?.id ?? ''),
  text
} }];

