// Extrait la reponse du modele et la borne pour Telegram (4096 caracteres max).
// parse_mode n'est PAS pose : un simple _ ou * produit par le modele ferait
// echouer l'API en 400 "can't parse entities" (cf. WORKPLAN.md §9).
// chat_id est relu chez Guard Chat, PAS dans l'entree : le noeud HTTP
// remplace integralement la charge utile par la reponse d'Ollama.
// C'est le meme piege que WORKPLAN.md §8.1, version HTTP.
const j = $input.first().json;
const chat_id = $('Guard Chat').first().json.chat_id;
if (!chat_id) throw new Error('chat_id introuvable en amont : la reponse ne peut pas etre adressee.');

const content = String(j.message?.content ?? j.response ?? '').trim();
if (!content) {
  throw new Error(
    'Reponse vide du modele (done_reason=' + (j.done_reason || 'n/a') +
    ', eval_count=' + (j.eval_count ?? 'n/a') + ')'
  );
}

const LIMITE = 4000;
const answer = content.length > LIMITE
  ? content.slice(0, LIMITE) + '\n\n[tronque par la limite Telegram]'
  : content;

return [{ json: {
  chat_id,
  answer,
  tronque: content.length > LIMITE,
  duree_s: typeof j.total_duration === 'number' ? Math.round(j.total_duration / 1e6 / 100) / 10 : null,
  eval_count: j.eval_count ?? null
} }];
